describe('Internet Connection Drop Error Message', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display friendly error message when internet connection drops', () => {
    // Intercept the initial API call
    cy.intercept('GET', '/api/user-data').as('initialData');
    cy.wait('@initialData');

    // Simulate internet connection loss
    cy.window().then((win) => {
      win.navigator.onLine = false;
    });

    // Attempt to refresh or make another API call
    cy.get('[data-testid="refresh-button"]').click();

    // Wait for the error state to appear
    cy.get('[data-testid="connection-error-message"]')
      .should('be.visible')
      .should('contain', 'You appear to be offline');

    // Verify friendly guidance is provided
    cy.get('[data-testid="connection-error-guidance"]')
      .should('be.visible')
      .should('contain', 'Please check your internet connection');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]')
      .should('be.visible')
      .should('contain', 'Try Again');

    // Verify main content is not visible or is replaced by error state
    cy.get('[data-testid="main-content"]').should('not.exist');
  });

  it('should hide error message when internet connection is restored', () => {
    // Simulate internet connection loss
    cy.window().then((win) => {
      win.navigator.onLine = false;
    });

    // Trigger connection drop
    cy.get('[data-testid="refresh-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="connection-error-message"]')
      .should('be.visible');

    // Restore internet connection
    cy.window().then((win) => {
      win.navigator.onLine = true;
    });

    // Wait for the retry button to be clicked and API call to succeed
    cy.get('[data-testid="retry-button"]').click();
    cy.intercept('GET', '/api/user-data').as('retryData');
    cy.wait('@retryData');

    // Verify error message is hidden
    cy.get('[data-testid="connection-error-message"]').should('not.exist');

    // Verify main content is restored
    cy.get('[data-testid="main-content"]')
      .should('be.visible')
      .should('contain', 'Dashboard');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Data loaded successfully');
  });
});
